/** sort ⇒ keyset SQL text */
function keysetSql(sort) {
  // Write your solution here
  const col = sort.replace('-', '');
  return `WHERE (${col}, id) < ($1, $2) ORDER BY ${col} DESC, id DESC LIMIT $3`;
}

