// Reference solution
function keysetSql(sort) {
  const desc = sort.startsWith('-');
  const col = sort.replace('-', '').replace(/[A-Z]/g, (ch) => '_' + ch.toLowerCase());
  const dir = desc ? 'DESC' : 'ASC';
  return `WHERE (${col}, id) ${desc ? '<' : '>'} ($1, $2) ORDER BY ${col} ${dir}, id ${dir} LIMIT $3`;
}
